def noisy(count):
    """Pretend this log is far too big to hold in memory."""
    for number in range(count):
        yield f"  temp={number}  " if number % 2 == 0 else "  skip  "


def cleaned(lines):
    for line in lines:
        yield line.strip()


def temps(rows):
    for row in rows:
        if row.startswith("temp="):
            yield int(row.split("=")[1])


print(sum(temps(cleaned(noisy(1000)))))
